if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface ProcessedRow {
  'Input OE': string;
  'XX CODE': string | null;
  'Application': string | null;
  'Year': string | null;
  'OEM': string | null;
  'Drive': string | null;
  'Picture': string | null;
  '广州价': string | number | null;
  [key: string]: any;
}

export type FileType = 'box1' | 'box2' | 'oe';

export interface FileState {
  file: File | null;
  name: string;
}

export interface Box1Data {
  xxCode: string;
  application: string;
  year: string;
  oem: string;
  drive: string;
  picture: string;
}

import * as XLSX from 'xlsx';
import { Box1Data, ProcessedRow } from '../types';

const normalize = (s: any): string => {
  if (s === null || s === undefined) return "";
  return String(s).replace(/[^A-Za-z0-9]/g, '').toUpperCase();
};

export const processFiles = async (
  fileBox1: File,
  fileBox2: File,
  fileOe: File
): Promise<ProcessedRow[]> => {
  // 1. Process BOX1 (Data Source)
  const buf1 = await fileBox1.arrayBuffer();
  const wb1 = XLSX.read(buf1);
  const ws1 = wb1.Sheets[wb1.SheetNames[0]];
  // Use header:1 to get array of arrays. Python script uses header=1 (row index 1)
  const data1 = XLSX.utils.sheet_to_json<any[]>(ws1, { header: 1 });

  // Heuristic: Try to find the header row containing 'OEM'
  // Python script explicitly says header=1, which implies the second row (index 1) contains headers.
  let headerIndex = 1;
  // Safety check: if index 1 doesn't exist or doesn't look like a header, try index 0
  if (!data1[1] || !data1[1].includes('OEM')) {
    const row0 = data1[0];
    if (row0 && row0.includes('OEM')) {
      headerIndex = 0;
    }
  }

  const headers1 = data1[headerIndex];
  const colMap1: Record<string, number> = {};
  if (headers1) {
    headers1.forEach((h: any, i: number) => {
      if (typeof h === 'string') colMap1[h.trim()] = i;
    });
  }

  const map1: Record<string, Box1Data> = {};

  for (let i = headerIndex + 1; i < data1.length; i++) {
    const row = data1[i];
    if (!row) continue;

    const oemRaw = row[colMap1['OEM']];
    if (!oemRaw) continue;

    // Split by whitespace/newline as per python script: str(oem_val).split()
    const tokens = String(oemRaw).split(/[\s\n]+/);

    for (const token of tokens) {
      const norm = normalize(token);
      if (norm) {
        map1[norm] = {
          xxCode: row[colMap1['XX CODE']],
          application: row[colMap1['Application']],
          year: row[colMap1['Year']],
          oem: row[colMap1['OEM']],
          drive: row[colMap1['Drive']],
          picture: row[colMap1['Picture']],
        };
      }
    }
  }

  // 2. Process BOX2 (Price Source)
  const buf2 = await fileBox2.arrayBuffer();
  const wb2 = XLSX.read(buf2);
  const ws2 = wb2.Sheets[wb2.SheetNames[0]];
  const data2 = XLSX.utils.sheet_to_json<any>(ws2); // Array of objects

  const priceMap: Record<string, string | number> = {};

  // Need to find columns for Code and Price flexibly
  // Python script looks for '编号' and '广州\n价格'
  data2.forEach(row => {
    const keys = Object.keys(row);
    // Find key for Code
    const codeKey = keys.find(k => k.includes('编号') || k.toUpperCase() === 'XX CODE' || k === 'CODE');
    // Find key for Price
    const priceKey = keys.find(k => k.includes('价格') || k.includes('Price') || k.includes('广州'));

    if (codeKey && priceKey) {
      const codeVal = row[codeKey];
      const priceVal = row[priceKey];
      if (codeVal !== undefined && codeVal !== null) {
        priceMap[String(codeVal).trim()] = priceVal;
      }
    }
  });

  // 3. Process OE (Input List)
  const buf3 = await fileOe.arrayBuffer();
  const wb3 = XLSX.read(buf3);
  const ws3 = wb3.Sheets[wb3.SheetNames[0]];
  const data3 = XLSX.utils.sheet_to_json<any>(ws3);

  const results: ProcessedRow[] = [];

  for (const row of data3) {
    // Find 'OE' column, or default to first key found
    const keys = Object.keys(row);
    const inputKey = keys.find(k => k.toUpperCase() === 'OE') || keys[0];
    const inputOE = row[inputKey];

    const normInput = normalize(inputOE);
    const match = map1[normInput];

    const newRow: ProcessedRow = {
      'Input OE': inputOE,
      'XX CODE': null,
      'Application': null,
      'Year': null,
      'OEM': null,
      'Drive': null,
      'Picture': null,
      '广州价': null,
    };

    if (match) {
      newRow['XX CODE'] = match.xxCode;
      newRow['Application'] = match.application;
      newRow['Year'] = match.year;
      newRow['OEM'] = match.oem;
      newRow['Drive'] = match.drive;
      newRow['Picture'] = match.picture;

      if (match.xxCode) {
        const price = priceMap[String(match.xxCode).trim()];
        newRow['广州价'] = price !== undefined ? price : null;
      }
    }

    results.push(newRow);
  }

  return results;
};

export const exportToExcel = (data: ProcessedRow[], fileName: string) => {
  const ws = XLSX.utils.json_to_sheet(data);
  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Matched Data");
  XLSX.writeFile(wb, fileName);
};

import React, { useRef } from 'react';
import { Upload, FileSpreadsheet, X, CheckCircle } from 'lucide-react';

interface FileUploaderProps {
  label: string;
  subLabel?: string;
  file: File | null;
  onFileSelect: (file: File) => void;
  onClear: () => void;
  accept?: string;
  color?: "blue" | "green" | "purple";
}

const FileUploader: React.FC<FileUploaderProps> = ({ 
  label, 
  subLabel, 
  file, 
  onFileSelect, 
  onClear, 
  accept = ".csv, .xlsx, .xls",
  color = "blue"
}) => {
  const inputRef = useRef<HTMLInputElement>(null);

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    if (e.dataTransfer.files && e.dataTransfer.files[0]) {
      onFileSelect(e.dataTransfer.files[0]);
    }
  };

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files[0]) {
      onFileSelect(e.target.files[0]);
    }
  };

  const colorClasses = {
    blue: "border-blue-200 bg-blue-50/50 hover:bg-blue-50 text-blue-600",
    green: "border-green-200 bg-green-50/50 hover:bg-green-50 text-green-600",
    purple: "border-purple-200 bg-purple-50/50 hover:bg-purple-50 text-purple-600",
  };

  const iconColors = {
    blue: "text-blue-500",
    green: "text-green-500",
    purple: "text-purple-500",
  };

  return (
    <div className="flex flex-col gap-2 w-full">
      <label className="text-sm font-semibold text-slate-700">{label}</label>

      {!file ? (
        <div 
          onClick={() => inputRef.current?.click()}
          onDragOver={(e) => e.preventDefault()}
          onDrop={handleDrop}
          className={`
            relative cursor-pointer group
            flex flex-col items-center justify-center 
            h-32 rounded-xl border-2 border-dashed 
            transition-all duration-200 ease-in-out
            ${colorClasses[color]}
          `}
        >
          <input 
            type="file" 
            ref={inputRef} 
            className="hidden" 
            accept={accept} 
            onChange={handleChange}
          />
          <div className={`p-3 rounded-full bg-white shadow-sm mb-2 group-hover:scale-110 transition-transform ${iconColors[color]}`}>
            <Upload size={20} />
          </div>
          <p className="text-sm font-medium">Click to upload or drag & drop</p>
          {subLabel && <p className="text-xs text-slate-500 mt-1">{subLabel}</p>}
        </div>
      ) : (
        <div className="relative flex items-center p-4 bg-white border border-slate-200 rounded-xl shadow-sm">
          <div className={`p-2 rounded-lg mr-3 bg-opacity-10 ${iconColors[color].replace('text-', 'bg-')}`}>
            <FileSpreadsheet className={iconColors[color]} size={24} />
          </div>
          <div className="flex-1 min-w-0">
            <p className="text-sm font-medium text-slate-900 truncate">{file.name}</p>
            <p className="text-xs text-slate-500">{(file.size / 1024).toFixed(1)} KB</p>
          </div>
          <div className="flex items-center gap-2">
            <CheckCircle size={18} className="text-emerald-500" />
            <button 
              onClick={onClear}
              className="p-1.5 text-slate-400 hover:text-red-500 hover:bg-red-50 rounded-lg transition-colors"
            >
              <X size={18} />
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default FileUploader;

