import XLSX from 'xlsx';
import { Box1Data, ProcessedRow } from '../types';

const normalize = (s: any): string => {
  if (s === null || s === undefined) return "";
  return String(s).replace(/[^A-Za-z0-9]/g, '').toUpperCase();
};

export const processFiles = async (
  fileBox1: File,
  fileBox2: File,
  fileOe: File
): Promise<ProcessedRow[]> => {
  // 1. Process BOX1 (Data Source)
  const buf1 = await fileBox1.arrayBuffer();
  const wb1 = XLSX.read(buf1, { type: 'array' });
  const ws1 = wb1.Sheets[wb1.SheetNames[0]];
  // Use header:1 to get array of arrays. Python script uses header=1 (row index 1)
  const data1 = XLSX.utils.sheet_to_json<any[]>(ws1, { header: 1 });

  // Heuristic: Try to find the header row containing 'OEM'
  // Python script explicitly says header=1, which implies the second row (index 1) contains headers.
  let headerIndex = 1;
  // Safety check: if index 1 doesn't exist or doesn't look like a header, try index 0
  if (!data1[1] || !data1[1].includes('OEM')) {
    const row0 = data1[0];
    if (row0 && row0.includes('OEM')) {
      headerIndex = 0;
    }
  }

  const headers1 = data1[headerIndex];
  const colMap1: Record<string, number> = {};
  if (headers1) {
    headers1.forEach((h: any, i: number) => {
      if (typeof h === 'string') colMap1[h.trim()] = i;
    });
  }

  const map1: Record<string, Box1Data> = {};

  for (let i = headerIndex + 1; i < data1.length; i++) {
    const row = data1[i];
    if (!row) continue;

    const oemRaw = row[colMap1['OEM']];
    if (!oemRaw) continue;

    // Split by whitespace/newline as per python script: str(oem_val).split()
    const tokens = String(oemRaw).split(/[\s\n]+/);

    for (const token of tokens) {
      const norm = normalize(token);
      if (norm) {
        map1[norm] = {
          xxCode: row[colMap1['XX CODE']],
          application: row[colMap1['Application']],
          year: row[colMap1['Year']],
          oem: row[colMap1['OEM']],
          drive: row[colMap1['Drive']],
          picture: row[colMap1['Picture']],
        };
      }
    }
  }

  // 2. Process BOX2 (Price Source)
  const buf2 = await fileBox2.arrayBuffer();
  const wb2 = XLSX.read(buf2, { type: 'array' });
  const ws2 = wb2.Sheets[wb2.SheetNames[0]];
  const data2 = XLSX.utils.sheet_to_json<any>(ws2); // Array of objects

  const priceMap: Record<string, string | number> = {};

  // Need to find columns for Code and Price flexibly
  // Python script looks for '编号' and '广州\n价格'
  data2.forEach(row => {
    const keys = Object.keys(row);
    // Find key for Code
    const codeKey = keys.find(k => k.includes('编号') || k.toUpperCase() === 'XX CODE' || k === 'CODE');
    // Find key for Price
    const priceKey = keys.find(k => k.includes('价格') || k.includes('Price') || k.includes('广州'));

    if (codeKey && priceKey) {
      const codeVal = row[codeKey];
      const priceVal = row[priceKey];
      if (codeVal !== undefined && codeVal !== null) {
        priceMap[String(codeVal).trim()] = priceVal;
      }
    }
  });

  // 3. Process OE (Input List)
  const buf3 = await fileOe.arrayBuffer();
  const wb3 = XLSX.read(buf3, { type: 'array' });
  const ws3 = wb3.Sheets[wb3.SheetNames[0]];
  const data3 = XLSX.utils.sheet_to_json<any>(ws3);

  const results: ProcessedRow[] = [];

  for (const row of data3) {
    // Find 'OE' column, or default to first key found
    const keys = Object.keys(row);
    const inputKey = keys.find(k => k.toUpperCase() === 'OE') || keys[0];
    const inputOE = row[inputKey];

    const normInput = normalize(inputOE);
    const match = map1[normInput];

    const newRow: ProcessedRow = {
      'Input OE': inputOE,
      'XX CODE': null,
      'Application': null,
      'Year': null,
      'OEM': null,
      'Drive': null,
      'Picture': null,
      '广州价': null,
    };

    if (match) {
      newRow['XX CODE'] = match.xxCode;
      newRow['Application'] = match.application;
      newRow['Year'] = match.year;
      newRow['OEM'] = match.oem;
      newRow['Drive'] = match.drive;
      newRow['Picture'] = match.picture;

      if (match.xxCode) {
        const price = priceMap[String(match.xxCode).trim()];
        newRow['广州价'] = price !== undefined ? price : null;
      }
    }

    results.push(newRow);
  }

  return results;
};

export const exportToExcel = (data: ProcessedRow[], fileName: string) => {
  const headers = ['Input OE', 'XX CODE', 'Application', 'Year', 'OEM', 'Drive', 'Picture', '广州价'];

  // Create sheet with explicit headers
  const ws = XLSX.utils.json_to_sheet(data, { header: headers });

  // Find the column index for 'OEM' (0-based)
  const oemColIndex = headers.indexOf('OEM'); // Should be 4

  // Iterate rows to apply style to matched OEM cells
  // data[i] corresponds to row i+2 in Excel (row 1 is header)
  data.forEach((row, idx) => {
    // A match exists if OEM is populated
    if (row['OEM']) {
      // Get the cell reference
      const cellAddress = XLSX.utils.encode_cell({ r: idx + 1, c: oemColIndex });

      // Ensure cell object exists
      if (!ws[cellAddress]) {
        ws[cellAddress] = { t: 's', v: row['OEM'] };
      }

      // Apply red font color using the 's' (style) property supported by xlsx-js-style
      ws[cellAddress].s = {
        font: {
          color: { rgb: "FF0000" },
          bold: true
        }
      };
    }
  });

  const wb = XLSX.utils.book_new();
  XLSX.utils.book_append_sheet(wb, ws, "Matched Data");
  XLSX.writeFile(wb, fileName);
};

