  const wbOe = XLSX.read(bufOe, { type: 'array' });
  const wsOe = wbOe.Sheets[wbOe.SheetNames[0]];
  const dataOe = XLSX.utils.sheet_to_json<any>(wsOe);

  const results: ProcessedRow[] = [];

  for (const row of dataOe) {
    const keys = Object.keys(row);
    const inputKey = keys.find(k => k.toUpperCase() === 'OE') || keys[0];
    const inputOE = row[inputKey];

    const normInput = normalize(inputOE);
    const match = mapRef[normInput];

    const newRow: ProcessedRow = {
      'Input OE': inputOE,
      'XX CODE': null,
      'Application': null,
      'Year': null,
      'OEM': null,
      'Drive': null,
      'Picture': null,
      '广州价': null,
    };

    if (match) {
      newRow['XX CODE'] = match.xxCode;
      newRow['Application'] = match.application;
      newRow['Year'] = match.year;
      newRow['OEM'] = match.oem;
      newRow['Drive'] = match.drive;
      newRow['Picture'] = match.picture;
      newRow['广州价'] = match.price;
    }

    results.push(newRow);
  }

  return results;
};

export const exportToExcel = async (data: ProcessedRow[], fileName: string) => {
  const workbook = new ExcelJS.Workbook();
  const worksheet = workbook.addWorksheet('Matched Results');

  const columns = ['Input OE', 'XX CODE', 'Application', 'Year', 'OEM', 'Drive', 'Picture', '广州价'];

  // Set up columns
  worksheet.columns = columns.map(c => ({ 
    header: c, 
    key: c, 
    width: c === 'OEM' || c === 'Application' ? 30 : 15 
  }));

  // Style Header
  worksheet.getRow(1).font = { bold: true };
  worksheet.getRow(1).fill = {
    type: 'pattern',
    pattern: 'solid',
    fgColor: { argb: 'FFF1F5F9' } // Slate-100
  };

  for (const row of data) {
    const newRow = worksheet.addRow({});

    columns.forEach((col, colIdx) => {
      const cell = newRow.getCell(colIdx + 1);
      const val = row[col];

      if (col === 'OEM' && val && row['Input OE']) {
        const oemStr = String(val);
        const inputNorm = normalize(row['Input OE']);

        // Split by whitespace/newline matching the logic used in processing
        // capturing the delimiters to reconstruct the string perfectly
        const parts = oemStr.split(/([\s\n]+)/);
        const richText: any[] = [];

        parts.forEach(part => {
           if (!part) return;

           // If strictly whitespace, just add it
           if (/^[\s\n]+$/.test(part)) {
             richText.push({ text: part });
           } else {
             // Token logic
             if (normalize(part) === inputNorm) {
               richText.push({ 
                 text: part, 
                 font: { color: { argb: 'FFFF0000' }, bold: true } 
               });
             } else {
               richText.push({ text: part });
             }
           }
        });

        cell.value = { richText };
      } else {
        cell.value = val;
      }
    });
  }

  // Write and Download
  const buffer = await workbook.xlsx.writeBuffer();
  const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });

  const url = window.URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = fileName;
  anchor.click();
  window.URL.revokeObjectURL(url);
};

