import * as XLSX from 'xlsx';
import ExcelJS from 'exceljs';
import { Box1Data, ProcessedRow } from '../types';

const normalize = (s: any): string => {
  if (s === null || s === undefined) return "";
  return String(s).replace(/[^A-Za-z0-9]/g, '').toUpperCase();
};

export const processFiles = async (
  fileReference: File,
  fileOe: File
): Promise<ProcessedRow[]> => {
  // 1. Process Reference Database (Data + Price)
  const bufRef = await fileReference.arrayBuffer();
  const wbRef = XLSX.read(bufRef, { type: 'array' });
  const wsRef = wbRef.Sheets[wbRef.SheetNames[0]];
  const dataRef = XLSX.utils.sheet_to_json<any[]>(wsRef, { header: 1 });

  // Heuristic: Try to find the header row containing 'OEM'
  let headerIndex = 1;
  // Safety check: if index 1 doesn't exist or doesn't look like a header, try index 0
  if (!dataRef[1] || !dataRef[1].includes('OEM')) {
    const row0 = dataRef[0];
    if (row0 && row0.includes('OEM')) {
      headerIndex = 0;
    }
  }

  const headers = dataRef[headerIndex];
  const colMap: Record<string, number> = {};

  // Dynamic column finding
  let priceColIndex = -1;

  if (headers) {
    headers.forEach((h: any, i: number) => {
      if (typeof h === 'string') {
        const headerName = h.trim();
        colMap[headerName] = i;

        // Identify Price Column (look for '广州', 'Price', '价格')
        if (priceColIndex === -1 && (
             headerName.includes('广州') || 
             headerName.includes('Price') || 
             headerName.includes('价格')
           )) {
          priceColIndex = i;
        }
      }
    });
  }

  const mapRef: Record<string, Box1Data> = {};

  for (let i = headerIndex + 1; i < dataRef.length; i++) {
    const row = dataRef[i];
    if (!row) continue;

    const oemRaw = row[colMap['OEM']];
    if (!oemRaw) continue;

    const tokens = String(oemRaw).split(/[\s\n]+/);

    // Extract Price from this row if column exists
    let rowPrice = null;
    if (priceColIndex !== -1) {
      rowPrice = row[priceColIndex];
    }

    for (const token of tokens) {
      const norm = normalize(token);
      if (norm) {
        mapRef[norm] = {
          xxCode: row[colMap['XX CODE']],
          application: row[colMap['Application']],
          year: row[colMap['Year']],
          oem: row[colMap['OEM']],
          drive: row[colMap['Drive']],
          picture: row[colMap['Picture']],
          price: rowPrice
        };
      }
    }
  }

  // 2. Process OE (Input List)
  const bufOe = await fileOe.arrayBuffer();
  const wbOe = XLSX.read(bufOe, { type: 'array' });
  const wsOe = wbOe.Sheets[wbOe.SheetNames[0]];
  const dataOe = XLSX.utils.sheet_to_json<any>(wsOe);

  const results: ProcessedRow[] = [];

  for (const row of dataOe) {
    const keys = Object.keys(row);
    const inputKey = keys.find(k => k.toUpperCase() === 'OE') || keys[0];
    const inputOE = row[inputKey];

    const normInput = normalize(inputOE);
    const match = mapRef[normInput];

    const newRow: ProcessedRow = {
      '输入 OE': inputOE,
      'XX 编码': null,
      '适用车型': null,
      '年份': null,
      'OEM': null,
      '驱动': null,
      '图片': null,
      '广州价': null,
    };

    if (match) {
      newRow['XX 编码'] = match.xxCode;
      newRow['适用车型'] = match.application;
      newRow['年份'] = match.year;
      newRow['OEM'] = match.oem;
      newRow['驱动'] = match.drive;
      newRow['图片'] = match.picture;
      newRow['广州价'] = match.price;
    }

    results.push(newRow);
  }

  return results;
};

