export const exportToExcel = async (data: ProcessedRow[], fileName: string) => {
  const workbook = new ExcelJS.Workbook();
  const worksheet = workbook.addWorksheet('匹配结果');

  // 尺寸计算 (96 DPI):
  // 1 磅 (Point) = 1/72 英寸
  // 2.15cm = (2.15 / 2.54) * 96 ≈ 81 像素 (图片高度)
  // 2.15cm = (2.15 / 2.54) * 72 ≈ 61 磅 (Excel 行高)
  // 6.0cm = (6.0 / 2.54) * 96 ≈ 227 像素 (图片宽度)
  // 列宽 34 约为 6.6cm，可容纳 6.0cm 的图片

  const columns = ['输入 OE', 'XX 编码', '适用车型', '年份', 'OEM', '驱动', '图片', '广州价'];
  worksheet.columns = columns.map(c => ({ 
    header: c, 
    key: c, 
    width: c === 'OEM' || c === '适用车型' ? 35 : (c === '图片' ? 34 : 15)
  }));

  worksheet.getRow(1).font = { bold: true };
  worksheet.getRow(1).height = 25;
  worksheet.getRow(1).alignment = { vertical: 'middle', horizontal: 'center' };
  worksheet.getRow(1).fill = {
    type: 'pattern',
    pattern: 'solid',
    fgColor: { argb: 'FFF1F5F9' }
  };

  for (let i = 0; i < data.length; i++) {
    const rowData = data[i];
    const excelRow = worksheet.addRow({});
    const rowNumber = i + 2;

    // 设置行高为 61 磅 (2.15cm)
    excelRow.height = 61;
    excelRow.alignment = { vertical: 'middle', horizontal: 'center' };

    columns.forEach((col, colIdx) => {
      const cell = excelRow.getCell(colIdx + 1);
      const val = rowData[col];

      if (col === '图片' && rowData['图片数据']) {
        const imgData = rowData['图片数据'];
        try {
          const imageId = workbook.addImage({
            buffer: imgData.buffer,
            extension: imgData.extension as any,
          });
          // 设置图片像素尺寸为 227px (6.0cm) x 81px (2.15cm)
          worksheet.addImage(imageId, {
            tl: { col: colIdx, row: rowNumber - 1 },
            ext: { width: 227, height: 81 },
            editAs: 'oneCell'
          });
        } catch (e) { console.error(e); }
        cell.value = "";
      } else if (col === 'OEM' && val && rowData['输入 OE']) {
        const oemStr = String(val);
        const inputNorm = normalize(rowData['输入 OE']);
        const parts = oemStr.split(/([\s\n,;:/|，；、]+)/);
        const richText: any[] = [];
        parts.forEach(part => {
           if (!part) return;
           if (/^[\s\n,;:/|，；、]+$/.test(part)) {
             richText.push({ text: part });
           } else {
             if (normalize(part) === inputNorm) {
               richText.push({ text: part, font: { color: { argb: 'FFFF0000' }, bold: true } });
             } else {
               richText.push({ text: part });
             }
           }
        });
        cell.value = { richText };
      } else {
        cell.value = val;
      }
    });
  }

  const buffer = await workbook.xlsx.writeBuffer();
  const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
  const url = window.URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = fileName;
  anchor.click();
  window.URL.revokeObjectURL(url);
};

import React, { useState, useEffect } from 'react';
import { ProcessedRow } from '../types';
import { ChevronLeft, ChevronRight, Download, ImageIcon } from 'lucide-react';

interface ResultsTableProps {
  data: ProcessedRow[];
  onExport: () => void;
}

const ImagePreview: React.FC<{ data?: { buffer: ArrayBuffer; extension: string } | null }> = ({ data }) => {
  const [url, setUrl] = useState<string | null>(null);

  useEffect(() => {
    if (data?.buffer) {
      const blob = new Blob([data.buffer], { type: `image/${data.extension}` });
      const objectUrl = URL.createObjectURL(blob);
      setUrl(objectUrl);
      return () => URL.revokeObjectURL(objectUrl);
    }
  }, [data]);

  if (!url) return <div className="flex items-center justify-center w-24 h-9 bg-slate-100 rounded text-slate-400"><ImageIcon size={16} /></div>;

  return (
    <img 
      src={url} 
      alt="Preview" 
      className="w-24 h-9 object-cover rounded border border-slate-200 shadow-sm" 
      style={{ aspectRatio: '60 / 21.5' }}
    />
  );
};

const ResultsTable: React.FC<ResultsTableProps> = ({ data, onExport }) => {
  const [currentPage, setCurrentPage] = useState(1);
  const rowsPerPage = 10;

  const totalPages = Math.ceil(data.length / rowsPerPage);
  const startIndex = (currentPage - 1) * rowsPerPage;
  const currentData = data.slice(startIndex, startIndex + rowsPerPage);

  const columns = [
    '输入 OE',
    'XX 编码',
    '适用车型',
    '年份',
    'OEM',
    '驱动',
    '图片',
    '广州价'
  ];

  const renderCellValue = (val: any) => {
    if (val === null || val === undefined) return "";
    if (typeof val === 'object') {
      // 处理 ExcelJS 可能残留的对象结构
      return val.result ?? val.text ?? String(val);
    }
    return String(val);
  };

  if (data.length === 0) return null;

  return (
    <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden animate-fade-in">
      <div className="flex items-center justify-between p-4 border-b border-slate-100 bg-slate-50/50">
        <div>
          <h3 className="text-lg font-bold text-slate-800">匹配结果</h3>
          <p className="text-sm text-slate-500">共 {data.length} 条记录 (包含图片提取)</p>
        </div>
        <button 
          onClick={onExport}
          className="flex items-center gap-2 px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-sm font-medium rounded-lg transition-colors shadow-sm"
        >
          <Download size={16} />
          导出包含图片的 Excel
        </button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-sm text-left">
          <thead className="text-xs text-slate-500 uppercase bg-slate-50 border-b border-slate-100">
            <tr>
              <th className="px-6 py-3 font-semibold">#</th>
              {columns.map(col => (
                <th key={col} className="px-6 py-3 font-semibold whitespace-nowrap">
                  {col}
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {currentData.map((row, idx) => (
              <tr key={startIndex + idx} className="hover:bg-slate-50 transition-colors">
                <td className="px-6 py-3 text-slate-400 font-mono text-xs">{startIndex + idx + 1}</td>
                {columns.map((col) => (
                  <td key={col} className="px-6 py-3 max-w-xs truncate" title={col !== '图片' ? renderCellValue(row[col]) : ''}>
                    {col === '图片' ? (
                      <ImagePreview data={row['图片数据']} />
                    ) : row[col] !== null ? (
                      <span className={
                        col === 'OEM' ? 'font-medium text-red-600' :
                        col === '输入 OE' ? 'font-medium text-slate-900' : 
                        'text-slate-600'
                      }>
                        {renderCellValue(row[col])}
                      </span>
                    ) : (
                      <span className="text-slate-300 italic">-</span>
                    )}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="flex items-center justify-between px-6 py-4 border-t border-slate-100 bg-slate-50/50">
        <div className="text-xs text-slate-500">
          显示第 {startIndex + 1} 至 {Math.min(startIndex + rowsPerPage, data.length)} 条，共 {data.length} 条
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
            disabled={currentPage === 1}
            className="p-1 rounded hover:bg-slate-200 disabled:opacity-30 disabled:hover:bg-transparent transition-colors"
          >
            <ChevronLeft size={20} />
          </button>
          <span className="flex items-center text-xs font-medium text-slate-600 px-2">
            第 {currentPage} 页 / 共 {totalPages} 页
          </span>
          <button
            onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
            disabled={currentPage === totalPages}
            className="p-1 rounded hover:bg-slate-200 disabled:opacity-30 disabled:hover:bg-transparent transition-colors"
          >
            <ChevronRight size={20} />
          </button>
        </div>
      </div>
    </div>
  );
};

export default ResultsTable;

