const normalize = (s: any): string => {
  if (s === null || s === undefined) return "";
  const str = typeof s === 'object' ? (s.text || s.result || String(s)) : String(s);
  return str.replace(/[^A-Za-z0-9]/g, '').toUpperCase();
};

const getCellValue = (cell: ExcelJS.Cell): any => {
  const val = cell.value;
  if (val === null || val === undefined) return "";
  if (typeof val === 'object' && 'result' in val) return val.result ?? "";
  if (typeof val === 'object' && 'text' in val) return val.text ?? "";
  if (typeof val === 'object' && 'richText' in val) return (val as any).richText.map((t: any) => t.text).join("");
  return val;
};

const findColIndex = (headers: any[], possibleNames: string[]): number => {
  for (let i = 0; i < headers.length; i++) {
    const h = String(headers[i] || "").trim().toUpperCase();
    if (possibleNames.some(name => h.includes(name.toUpperCase()))) return i;
  }
  return -1;
};

/**
 * Exponential backoff helper to handle 429 quota errors
 */
async function callWithRetry<T>(fn: () => Promise<T>, maxRetries: number = 3, initialDelay: number = 2000): Promise<T> {
  let lastError: any;
  for (let i = 0; i < maxRetries; i++) {
    try {
      return await fn();
    } catch (error: any) {
      lastError = error;
      const isQuotaError = error.message?.includes('429') || error.message?.includes('RESOURCE_EXHAUSTED') || error.status === 429;
      if (isQuotaError && i < maxRetries - 1) {
        const delay = initialDelay * Math.pow(2, i);
        console.warn(`Quota hit, retrying in ${delay}ms... (Attempt ${i + 1}/${maxRetries})`);
        await new Promise(resolve => setTimeout(resolve, delay));
        continue;
      }
      throw error;
    }
  }
  throw lastError;
}

/**
 * Search part info using Gemini AI
 */
async function fetchPartInfoFromAI(oe: string): Promise<{ productName: string, model: string, crossOE: string, url: string }> {
  return await callWithRetry(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Search for automotive part with OE/OEM number: ${oe}. 
      Provide:
      1. Product Name (e.g., Steering Rack).
      2. Compatible vehicle models.
      3. Alternative or General OE numbers.
      Return strictly as JSON.`,
      config: {
        tools: [{ googleSearch: {} }],
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            productName: { type: Type.STRING, description: "Type of part" },
            model: { type: Type.STRING, description: "Vehicle models" },
            crossOE: { type: Type.STRING, description: "Cross reference OE numbers" },
          },
          required: ["productName", "model", "crossOE"]
        }
      }
    });

    let result = { productName: "", model: "", crossOE: "", url: "" };
    try {
      const jsonStr = response.text.trim();
      const parsed = JSON.parse(jsonStr);
      result.productName = parsed.productName || "";
      result.model = parsed.model || "";
      result.crossOE = parsed.crossOE || "";
    } catch (e) {
      console.warn("AI JSON parse error", e);
    }

    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks;
    if (chunks && chunks.length > 0) {
      const firstChunk = chunks.find((c: any) => c.web?.uri);
      if (firstChunk) result.url = firstChunk.web.uri;
    }

    return result;
  });
}

export const processFiles = async (
  fileReference: File,
  fileOe: File,
  onProgress?: (msg: string) => void
): Promise<{ results: ProcessedRow[], knownOEs: Set<string> }> => {
  onProgress?.("正在读取参考数据库...");
  const refBuffer = await fileReference.arrayBuffer();
  const refWorkbook = new ExcelJS.Workbook();
  await refWorkbook.xlsx.load(refBuffer);
  const refWorksheet = refWorkbook.worksheets[0];

  let headerRowIndex = 1;
  let oemColIdx = -1;
  for (let i = 1; i <= 20; i++) {
    const rowValues = refWorksheet.getRow(i).values as any[];
    oemColIdx = findColIndex(rowValues, ['OEM', 'OE', '原厂编号', '零件号']);
    if (oemColIdx !== -1) { headerRowIndex = i; break; }
  }

  if (oemColIdx === -1) throw new Error("参考数据库中未找到包含 'OEM' 的列。");

  const headers = refWorksheet.getRow(headerRowIndex).values as any[];
  const xxColIdx = findColIndex(headers, ['XX CODE', 'XX编码', '公司编号']);
  const appColIdx = findColIndex(headers, ['Application', '适用车型', '车型']);
  const yearColIdx = findColIndex(headers, ['Year', '年份', '年度']);
  const driveColIdx = findColIndex(headers, ['Drive', '驱动', '左/右']);
  const priceColIdx = findColIndex(headers, ['广州', 'Price', '价格', '单价']);
  const prodColIdx = findColIndex(headers, ['Product', 'Description', '名称', '产品名', '品名']);

  const imageMap: Record<number, { buffer: ArrayBuffer; extension: string }> = {};
  refWorksheet.getImages().forEach((image) => {
    const img = refWorkbook.model.media.find((m: any, idx: number) => idx === (image as any).imageId || m.index === (image as any).imageId);
    if (img && image.range.tl.nativeRow + 1) {
      imageMap[image.range.tl.nativeRow + 1] = { buffer: img.buffer, extension: img.extension };
    }
  });

  const mapRef: Record<string, Box1Data> = {};
  const knownOEs = new Set<string>();

  refWorksheet.eachRow((row, rowNumber) => {
    if (rowNumber <= headerRowIndex) return;
    const oemRaw = getCellValue(row.getCell(oemColIdx));
    if (!oemRaw) return;
    const tokens = String(oemRaw).split(/[\s\n,;:/|，；、]+/);
    const imageData = imageMap[rowNumber] || null;
    for (const token of tokens) {
      const norm = normalize(token);
      if (norm && norm.length > 2) {
        knownOEs.add(norm);
        mapRef[norm] = {
          xxCode: xxColIdx !== -1 ? String(getCellValue(row.getCell(xxColIdx)) || "") : "",
          application: appColIdx !== -1 ? String(getCellValue(row.getCell(appColIdx)) || "") : "",
          year: yearColIdx !== -1 ? String(getCellValue(row.getCell(yearColIdx)) || "") : "",
          oem: String(oemRaw),
          drive: driveColIdx !== -1 ? String(getCellValue(row.getCell(driveColIdx)) || "") : "",
          picture: "已提取",
          productName: prodColIdx !== -1 ? String(getCellValue(row.getCell(prodColIdx)) || "") : "",
          price: priceColIdx !== -1 ? getCellValue(row.getCell(priceColIdx)) : null,
          imageData: imageData
        };
      }
    }
  });

  onProgress?.("正在读取待处理 OE 列表...");
  const bufOe = await fileOe.arrayBuffer();
  const wbOe = XLSX.read(bufOe, { type: 'array' });
  const wsOe = wbOe.Sheets[wbOe.SheetNames[0]];
  const dataOeRaw = XLSX.utils.sheet_to_json<any[]>(wsOe, { header: 1 });

  let oeInputCol = 0;
  if (dataOeRaw.length > 0) {
    const firstRow = dataOeRaw[0];
    const detectedIdx = findColIndex(firstRow, ['OE', 'OEM', '查询', '输入']);
    if (detectedIdx !== -1) oeInputCol = detectedIdx - 1; 
    if (oeInputCol < 0) oeInputCol = 0;
  }

  const results: ProcessedRow[] = [];
  const startIdx = findColIndex(dataOeRaw[0], ['OE', 'OEM', '零件']) !== -1 ? 1 : 0;

  for (let i = startIdx; i < dataOeRaw.length; i++) {
    const row = dataOeRaw[i];
    if (!row || row.length === 0) continue;
    const inputOE = String(row[oeInputCol] || "").trim();
    if (!inputOE) continue;

    const normInput = normalize(inputOE);
    const match = mapRef[normInput];

    const newRow: ProcessedRow = {
      '输入 OE': inputOE,
      'XX 编码': null,
      '适用车型': null,
      '年份': null,
      'OEM': null,
      '驱动': null,
      '图片': null,
      '图片数据': null,
      '广州价': null,
      '产品名': null,
      '车型': null,
      '通用OE': null,
      '来源网址': null
    };

    if (match) {
      newRow['XX 编码'] = match.xxCode;
      newRow['适用车型'] = match.application;
      newRow['年份'] = match.year;
      newRow['OEM'] = match.oem;
      newRow['驱动'] = match.drive;
      newRow['图片'] = match.imageData ? "匹配成功" : "无图片";
      newRow['图片数据'] = match.imageData;
      newRow['广州价'] = match.price;
      newRow['产品名'] = match.productName;
    } else {
      onProgress?.(`未命中库，正在 AI 检索: ${inputOE}...`);
      try {
        const aiData = await fetchPartInfoFromAI(inputOE);
        newRow['产品名'] = aiData.productName;
        newRow['车型'] = aiData.model;
        newRow['通用OE'] = aiData.crossOE;
        newRow['来源网址'] = aiData.url;
      } catch (err) {
        newRow['产品名'] = "检索失败 (请检查 API 额度)";
        console.error(`AI Fetch skipped for ${inputOE}:`, err);
      }
    }

    results.push(newRow);
  }

  onProgress?.("处理完成。");
  return { results, knownOEs };
};

export const exportToExcel = async (data: ProcessedRow[], fileName: string, knownOEs: Set<string> = new Set()) => {
  const workbook = new ExcelJS.Workbook();
  const worksheet = workbook.addWorksheet('匹配结果');

  const horizOffsetEMU = 12 * 9525; 
  const vertOffsetEMU = 0;

  const columns = [
    '输入 OE',   // A
    'XX 编码',   // B
    '适用车型', // C
    '年份',     // D
    'OEM',      // E
    '驱动',     // F
    '图片',     // G
    '广州价',   // H
    '产品名',   // I
    '车型',     // J
    '通用OE',   // K
    '来源网址'   // L
  ];

  worksheet.columns = columns.map(c => ({ 
    header: c, 
    key: c, 
    width: (c === 'OEM' || c === '适用车型' || c === '车型' || c === '来源网址' || c === '通用OE' || c === '产品名') ? 35 : (c === '图片' ? 34 : 15)
  }));

  worksheet.getRow(1).font = { bold: true };
  worksheet.getRow(1).height = 25;
  worksheet.getRow(1).alignment = { vertical: 'middle', horizontal: 'center' };
  worksheet.getRow(1).fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF1F5F9' } };

  for (let i = 0; i < data.length; i++) {
    const rowData = data[i];
    const excelRow = worksheet.addRow({});
    const rowNumber = i + 2;
    excelRow.height = 80; 
    excelRow.alignment = { vertical: 'middle', horizontal: 'center' };

    columns.forEach((col, colIdx) => {
      const cell = excelRow.getCell(colIdx + 1);
      const val = rowData[col];

      if (col === '图片' && rowData['图片数据']) {
        const imgData = rowData['图片数据'];
        try {
          const imageId = workbook.addImage({ buffer: imgData.buffer, extension: imgData.extension as any });
          worksheet.addImage(imageId, {
            tl: { col: colIdx, row: rowNumber - 1, nativeColOff: horizOffsetEMU, nativeRowOff: vertOffsetEMU },
            ext: { width: 227, height: 81 },
            editAs: 'oneCell'
          });
        } catch (e) { console.error(e); }
        cell.value = "";
      } else if (col === '产品名' || col === '适用车型' || col === '车型') {
        cell.value = val;
        cell.alignment = { wrapText: true, vertical: 'middle', horizontal: 'center' };
      } else if (col === 'OEM' || col === '通用OE') {
        cell.alignment = { wrapText: true, vertical: 'middle', horizontal: 'center' };
        if (val && rowData['输入 OE']) {
          const contentStr = String(val);
          const inputNorm = normalize(rowData['输入 OE']);
          const parts = contentStr.split(/([\s\n,;:/|，；、]+)/);
          const richText: any[] = [];

          parts.forEach(part => {
             if (!part) return;
             const partNorm = normalize(part);
             if (/^[\s\n,;:/|，；、]+$/.test(part)) {
               richText.push({ text: part });
             } else if (partNorm === inputNorm) {
               // Red for input OE
               richText.push({ text: part, font: { color: { argb: 'FFFF0000' }, bold: true } });
             } else if (knownOEs.has(partNorm)) {
               // Green for database match
               richText.push({ text: part, font: { color: { argb: 'FF00B050' }, bold: true } });
             } else {
               richText.push({ text: part });
             }
          });
          cell.value = { richText };
        } else {
          cell.value = val;
        }
      } else if (col === '来源网址' && val) {
        cell.value = { text: val, hyperlink: val };
        cell.font = { color: { argb: 'FF0000FF' }, underline: true };
        cell.alignment = { vertical: 'middle', horizontal: 'center' };
      } else {
        cell.value = val;
      }
    });
  }

  const buffer = await workbook.xlsx.writeBuffer();
  const blob = new Blob([buffer], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
  const url = window.URL.createObjectURL(blob);
  const anchor = document.createElement('a');
  anchor.href = url;
  anchor.download = fileName;
  anchor.click();
  window.URL.revokeObjectURL(url);
};

import React, { useState, useEffect } from 'react';
import { ProcessedRow } from '../types';
import { ChevronLeft, ChevronRight, Download, ImageIcon, ExternalLink } from 'lucide-react';

interface ResultsTableProps {
  data: ProcessedRow[];
  knownOEs?: Set<string>;
  onExport: () => void;
}

const normalize = (s: any): string => {
  if (s === null || s === undefined) return "";
  const str = String(s);
  return str.replace(/[^A-Za-z0-9]/g, '').toUpperCase();
};

const ImagePreview: React.FC<{ data?: { buffer: ArrayBuffer; extension: string } | null }> = ({ data }) => {
  const [url, setUrl] = useState<string | null>(null);

  useEffect(() => {
    if (data?.buffer) {
      const blob = new Blob([data.buffer], { type: `image/${data.extension}` });
      const objectUrl = URL.createObjectURL(blob);
      setUrl(objectUrl);
      return () => URL.revokeObjectURL(objectUrl);
    }
  }, [data]);

  if (!url) return <div className="flex items-center justify-center w-24 h-9 bg-slate-100 rounded text-slate-400"><ImageIcon size={16} /></div>;

  return (
    <img 
      src={url} 
      alt="Preview" 
      className="w-24 h-9 object-cover rounded border border-slate-200 shadow-sm" 
      style={{ aspectRatio: '60 / 21.5' }}
    />
  );
};

const HighlightedText: React.FC<{ text: string; inputOE: string; knownOEs?: Set<string>; baseClass: string }> = ({ text, inputOE, knownOEs, baseClass }) => {
  if (!text) return null;
  const inputNorm = inputOE ? normalize(inputOE) : "";
  const parts = text.split(/([\s\n,;:/|，；、]+)/);

  return (
    <span className={baseClass}>
      {parts.map((part, i) => {
        if (!part) return null;
        const partNorm = normalize(part);
        const isInputMatch = inputNorm && partNorm === inputNorm;
        const isLibraryMatch = knownOEs && knownOEs.has(partNorm);

        let colorClass = "";
        if (isInputMatch) colorClass = "text-red-600 font-bold";
        else if (isLibraryMatch) colorClass = "text-emerald-600 font-bold";

        return (
          <span key={i} className={colorClass}>
            {part}
          </span>
        );
      })}
    </span>
  );
};

const ResultsTable: React.FC<ResultsTableProps> = ({ data, knownOEs, onExport }) => {
  const [currentPage, setCurrentPage] = useState(1);
  const rowsPerPage = 10;

  const totalPages = Math.ceil(data.length / rowsPerPage);
  const startIndex = (currentPage - 1) * rowsPerPage;
  const currentData = data.slice(startIndex, startIndex + rowsPerPage);

  const columns = [
    '输入 OE',
    'XX 编码',
    '适用车型',
    '年份',
    'OEM',
    '驱动',
    '图片',
    '广州价',
    '产品名',
    '车型',
    '通用OE',
    '来源网址'
  ];

  const renderCellValue = (val: any) => {
    if (val === null || val === undefined) return "";
    if (typeof val === 'object') {
      return val.result ?? val.text ?? String(val);
    }
    return String(val);
  };

  if (data.length === 0) return null;

  return (
    <div className="bg-white border border-slate-200 rounded-xl shadow-sm overflow-hidden animate-fade-in">
      <div className="flex items-center justify-between p-4 border-b border-slate-100 bg-slate-50/50">
        <div>
          <h3 className="text-lg font-bold text-slate-800">匹配结果</h3>
          <p className="text-sm text-slate-500">共 {data.length} 条记录 (支持 AI 自动检索未命中项)</p>
        </div>
        <button 
          onClick={onExport}
          className="flex items-center gap-2 px-4 py-2 bg-emerald-600 hover:bg-emerald-700 text-white text-sm font-medium rounded-lg transition-colors shadow-sm"
        >
          <Download size={16} />
          导出包含 AI 结果的 Excel
        </button>
      </div>

      <div className="overflow-x-auto">
        <table className="w-full text-sm text-left table-fixed">
          <thead className="text-xs text-slate-500 uppercase bg-slate-50 border-b border-slate-100">
            <tr>
              <th className="w-12 px-4 py-3 font-semibold">#</th>
              {columns.map(col => (
                <th key={col} className={`px-4 py-3 font-semibold whitespace-nowrap ${
                  (col === '车型' || col === '通用OE' || col === 'OEM' || col === '产品名') ? 'w-48' : 'w-32'
                }`}>
                  {col}
                </th>
              ))}
            </tr>
          </thead>
          <tbody className="divide-y divide-slate-100">
            {currentData.map((row, idx) => (
              <tr key={startIndex + idx} className="hover:bg-slate-50 transition-colors">
                <td className="px-4 py-3 text-slate-400 font-mono text-xs">{startIndex + idx + 1}</td>
                {columns.map((col) => (
                  <td key={col} className={`px-4 py-3 align-middle ${
                    (col === '车型' || col === '通用OE' || col === 'OEM' || col === '产品名' || col === '适用车型') ? 'whitespace-normal break-words' : 'truncate'
                  }`} title={(col !== '图片' && col !== '车型' && col !== '通用OE' && col !== 'OEM' && col !== '产品名') ? renderCellValue(row[col]) : ''}>
                    {col === '图片' ? (
                      <ImagePreview data={row['图片数据']} />
                    ) : col === '来源网址' && row[col] ? (
                      <a href={row[col]} target="_blank" rel="noopener noreferrer" className="flex items-center gap-1 text-blue-600 hover:underline">
                        <ExternalLink size={14} />
                        查看链接
                      </a>
                    ) : (col === 'OEM' || col === '通用OE') ? (
                      <HighlightedText 
                        text={renderCellValue(row[col])} 
                        inputOE={row['输入 OE']} 
                        knownOEs={knownOEs}
                        baseClass={col === 'OEM' ? "font-medium text-slate-600" : "text-indigo-600 italic"} 
                      />
                    ) : row[col] !== null ? (
                      <span className={
                        col === '输入 OE' ? 'font-medium text-slate-900' : 
                        col === '车型' ? 'text-indigo-600 italic' :
                        col === '产品名' ? 'font-semibold text-slate-700' :
                        'text-slate-600'
                      }>
                        {renderCellValue(row[col])}
                      </span>
                    ) : (
                      <span className="text-slate-300 italic">-</span>
                    )}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="flex items-center justify-between px-6 py-4 border-t border-slate-100 bg-slate-50/50">
        <div className="text-xs text-slate-500">
          显示第 {startIndex + 1} 至 {Math.min(startIndex + rowsPerPage, data.length)} 条，共 {data.length} 条
        </div>
        <div className="flex gap-2">
          <button
            onClick={() => setCurrentPage(p => Math.max(1, p - 1))}
            disabled={currentPage === 1}
            className="p-1 rounded hover:bg-slate-200 disabled:opacity-30 disabled:hover:bg-transparent transition-colors"
          >
            <ChevronLeft size={20} />
          </button>
          <span className="flex items-center text-xs font-medium text-slate-600 px-2">
            第 {currentPage} 页 / 共 {totalPages} 页
          </span>
          <button
            onClick={() => setCurrentPage(p => Math.min(totalPages, p + 1))}
            disabled={currentPage === totalPages}
            className="p-1 rounded hover:bg-slate-200 disabled:opacity-30 disabled:hover:bg-transparent transition-colors"
          >
            <ChevronRight size={20} />
          </button>
        </div>
      </div>
    </div>
  );
};

