              </button>
            )}
          </div>
        </div>

        {/* Results */}
        {results.length > 0 && (
           <ResultsTable 
             data={results} 
             knownOEs={knownOEs}
             onExport={() => exportToExcel(results, 'matched_results_with_ai.xlsx', knownOEs)} 
           />
        )}
      </main>
    </div>
  );
};

